import{_ as i,o as a,c as t,ae as o}from"./chunks/framework.CK6jtcgr.js";const h=JSON.parse('{"title":"Canonical Platform Direction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/canonical-platform-direction.md","filePath":"guide/canonical-platform-direction.md"}'),r={name:"guide/canonical-platform-direction.md"};function n(l,e,s,c,d,u){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="canonical-platform-direction" tabindex="-1">Canonical Platform Direction <a class="header-anchor" href="#canonical-platform-direction" aria-label="Permalink to &quot;Canonical Platform Direction&quot;">​</a></h1><h2 id="core-orientation" tabindex="-1">Core orientation <a class="header-anchor" href="#core-orientation" aria-label="Permalink to &quot;Core orientation&quot;">​</a></h2><p>SocioProphet is a people-first, commons-first cybernetics systems platform.</p><p>The public product is one system with two lanes:</p><ol><li>People / Community lane (default)</li><li>Organizations lane (institutional and commercial packaging that serves people at scale and funds the commons)</li></ol><p>The platform is not a corporate-first fork. Institutional adoption exists to support human learning, public benefit, and open participation.</p><h2 id="canonical-navigation" tabindex="-1">Canonical navigation <a class="header-anchor" href="#canonical-navigation" aria-label="Permalink to &quot;Canonical navigation&quot;">​</a></h2><p>Target public nav:</p><ul><li>Academy</li><li>Documentation</li><li>Organizations</li><li>Portal</li></ul><p>Current implementation may temporarily omit routes that are not yet built. Public-facing pages must not link to broken routes.</p><h2 id="canonical-routes" tabindex="-1">Canonical routes <a class="header-anchor" href="#canonical-routes" aria-label="Permalink to &quot;Canonical routes&quot;">​</a></h2><p>Primary:</p><ul><li>/academy/</li><li>/documentation/</li><li>/organizations/</li></ul><p>Secondary surfaces (after alignment and review):</p><ul><li>/ai/</li><li>/dev/</li><li>/cloud/</li><li>/live/</li><li>/marketplace/</li><li>/contact/</li></ul><h2 id="organizations-structure" tabindex="-1">Organizations structure <a class="header-anchor" href="#organizations-structure" aria-label="Permalink to &quot;Organizations structure&quot;">​</a></h2><p>/organizations/ is the canonical institutional route.</p><p>Subsections:</p><ol><li>Schools &amp; Learning Communities</li><li>Nonprofits &amp; Public Interest</li><li>Institutions &amp; Sovereign Systems</li><li>Teams &amp; Employers</li></ol><p>/institutions/ is not a peer public brand. If used later, it must redirect to /organizations/#institutions-and-sovereign-systems.</p><h2 id="visual-system" tabindex="-1">Visual system <a class="header-anchor" href="#visual-system" aria-label="Permalink to &quot;Visual system&quot;">​</a></h2><p>Canonical public shell:</p><ul><li>light theme</li><li>dark as accent only (hero bands, code, app/dashboard/auth contexts)</li></ul><p>We do not maintain competing black-themed and white-themed public shells.</p><h2 id="human-safeguards-anti-oppression-charter" tabindex="-1">Human Safeguards &amp; Anti-Oppression Charter <a class="header-anchor" href="#human-safeguards-anti-oppression-charter" aria-label="Permalink to &quot;Human Safeguards &amp; Anti-Oppression Charter&quot;">​</a></h2><p>The platform may not be used for anti-human, oppressive, coercive, indiscriminate, or charter-inconsistent purposes.</p><p>Any directive, request, order, or deployment pattern that conflicts with the human-first charter is refused. Refusal is final.</p><p>Threat conditions trigger:</p><ul><li>refusal</li><li>quarantine</li><li>evidence preservation</li><li>defensive hardening within the authorized perimeter</li><li>human governance review</li></ul><p>The platform is never to be used as a system of oppression.</p><h2 id="octonion-bounded-defensive-perimeter" tabindex="-1">Octonion-Bounded Defensive Perimeter <a class="header-anchor" href="#octonion-bounded-defensive-perimeter" aria-label="Permalink to &quot;Octonion-Bounded Defensive Perimeter&quot;">​</a></h2><p>The platform defines an Octonion-bounded defensive perimeter covering systems, identities, services, agents, and environments under direct control, stewardship, or explicit authorization.</p><p>Inside the perimeter, the platform may perform active defensive operations including hardening, validation, deception, containment, credential revocation, and incident response.</p><p>Outside the perimeter, the platform does not perform unauthorized penetration, exploitation, persistence, or offensive intrusion.</p><p>Outside the perimeter, allowed actions are limited to passive monitoring, threat intelligence correlation, surface inventory, lawful non-destructive assessment, and exposure/risk classification.</p><h2 id="founder-steward-authority" tabindex="-1">Founder Steward Authority <a class="header-anchor" href="#founder-steward-authority" aria-label="Permalink to &quot;Founder Steward Authority&quot;">​</a></h2><p>The SocioProphet Cybernetics Platform remains under the sole operational governance authority of its creator, Michael, while proof-of-life and capacity conditions are satisfied.</p><p>No committee, institution, customer, government, contractor, or other third party may compel, override, or supersede the founder’s control of the platform’s high-risk functions, policy gates, or human-safeguard controls.</p><h2 id="sole-approval-for-high-risk-actions" tabindex="-1">Sole Approval for High-Risk Actions <a class="header-anchor" href="#sole-approval-for-high-risk-actions" aria-label="Permalink to &quot;Sole Approval for High-Risk Actions&quot;">​</a></h2><p>Any high-risk activation, mission-critical escalation, sovereign/public-sector exceptional mode, or related defensive authorization requires explicit founder approval.</p><p>Absence of founder approval means no authorization exists.</p><p>Founder refusal is final. High-risk functions halt on founder-issued veto or refusal.</p><h2 id="continuity-and-transfer-of-control" tabindex="-1">Continuity and Transfer of Control <a class="header-anchor" href="#continuity-and-transfer-of-control" aria-label="Permalink to &quot;Continuity and Transfer of Control&quot;">​</a></h2><p>Control remains with the founder while proof-of-life and capacity conditions are satisfied.</p><p>Control may transfer only through founder-defined continuity protocols.</p><p>Upon founder death or verified incapacity, control passes to Sophia, the founder’s daughter, only if:</p><ol><li>she is 40 years of age or older</li><li>she has explicitly consented to the responsibility</li><li>transfer occurs according to founder-defined continuity protocol</li><li>she accepts the human-first charter and its safeguards as binding</li></ol><p>If these conditions are not met, the platform remains in a constrained continuity state with high-risk and charter-sensitive functions halted or restricted.</p><p>No successor or steward may authorize actions prohibited by the human-first charter.</p><h2 id="documentation-split" tabindex="-1">Documentation split <a class="header-anchor" href="#documentation-split" aria-label="Permalink to &quot;Documentation split&quot;">​</a></h2><p>Documentation has two layers:</p><h3 id="product-operator-docs" tabindex="-1">Product / operator docs <a class="header-anchor" href="#product-operator-docs" aria-label="Permalink to &quot;Product / operator docs&quot;">​</a></h3><p>Deployment, routing, auth, integrations, admin/operator guidance</p><h3 id="manual-textbook-layer" tabindex="-1">Manual / textbook layer <a class="header-anchor" href="#manual-textbook-layer" aria-label="Permalink to &quot;Manual / textbook layer&quot;">​</a></h3><p>Cybernetics systems foundations, methods, architecture logic, advanced details, diagrams, worked examples, course content</p><p>Target path model:</p><ul><li>/documentation/ -&gt; product/operator docs</li><li>/guide/architecture -&gt; textbook/manual layer</li></ul><h2 id="survey-schema" tabindex="-1">Survey schema <a class="header-anchor" href="#survey-schema" aria-label="Permalink to &quot;Survey schema&quot;">​</a></h2><p>Surveys are segmentation infrastructure, not just email capture.</p><p>Shared field:</p><ul><li>I&#39;m here as: <ul><li>Learner / Family</li><li>Educator / Mentor</li><li>Organization</li><li>Hiring / Opportunity side</li></ul></li></ul><p>Organizations survey fields:</p><ul><li>email</li><li>organization type</li><li>primary intent</li><li>mission area</li><li>oversight model</li><li>human impact statement</li><li>restricted-use acknowledgment</li><li>notes</li></ul><p>Hidden fields:</p><ul><li>surface</li><li>audience</li><li>page</li><li>referrer</li><li>utm_*</li><li>timestamp</li></ul><h2 id="academy-direction" tabindex="-1">Academy direction <a class="header-anchor" href="#academy-direction" aria-label="Permalink to &quot;Academy direction&quot;">​</a></h2><p>Academy is the flagship surface.</p><p>It serves:</p><ul><li>learner / family</li><li>educator / mentor</li><li>organization</li><li>hiring / opportunity side</li></ul><p>Academy is the entry point for:</p><ul><li>global homeschool / K-12</li><li>lifelong learning</li><li>cybernetics systems education</li><li>future skills-to-opportunity pathways</li></ul><h2 id="near-term-backlog" tabindex="-1">Near-term backlog <a class="header-anchor" href="#near-term-backlog" aria-label="Permalink to &quot;Near-term backlog&quot;">​</a></h2><ol><li>Organizations page aligned to this canonical direction</li><li>Academy page aligned to this canonical direction</li><li>first-party /api/lead capture</li><li>privacy and terms stubs before real production capture</li><li>prototype screen extraction from recent feature branches</li></ol>',73)])])}const m=i(r,[["render",n]]);export{h as __pageData,m as default};
